tool_calls.arguments:
{"command":"cat <<'EOF' > /tmp/test-connectivity.sh
#!/bin/bash
kubectl run -n client-ns curl-test --image=curlimages/curl:latest --rm -it -- wget -qO- http://server.server-ns.svc.cluster.local:80 --no-check-certificate
EOF
chmod +x /tmp/test-connectivity.sh
kubectl exec -n client-ns allowed-client -- /tmp/test-connectivity.sh 2>&1 || echo "Test command failed""}

